"""CON-02 (runner part): every vector file synced into `contracts/vectors/` is regenerated byte for byte by the
runner copy, so a new section in agent-core without a runner counterpart is visible here; the runner-only checks of
sections the copied tests do not cover (`admin_catch_up`)."""

from __future__ import annotations

import json
from pathlib import Path

from agent_runner.crypto import vectors
from agent_runner.crypto.log import catchup, wraps
from agent_runner.crypto.log import vectors as log_vectors

VECTORS = Path(__file__).resolve().parents[4] / "contracts" / "vectors"


def test_every_vector_file_has_a_runner_section() -> None:
    sections = vectors.discover()
    assert sorted(f"{section.name}.json" for section in sections) == sorted(
        path.name for path in VECTORS.glob("*.json")
    )
    assert vectors.stale(VECTORS, sections) == []


def test_admin_catch_up_vectors() -> None:
    """ADR-065 section 2 (`log-wraps.json` `admin_catch_up`): an admin reading a workgroup by inheritance is planned
    every epoch, against the log prefix named by the section. The copied `test_vectors_log.py` runs the `valid` and
    `invalid` wrap cases, including those on the `edge` log."""
    data = json.loads((VECTORS / "log-wraps.json").read_text(encoding="utf-8"))
    section = data["admin_catch_up"]
    log = log_vectors.Context(data["logs"]).log({"log": section["log"], "founder": data["founder"]})
    existing = [wraps.WrapSlot(s["scope"], s["scope_id"], s["epoch"], s["recipient_id"]) for s in section["existing"]]
    assert section["plans"]
    for plan in section["plans"]:
        missing = catchup.missing_wraps(log, plan["wrapper"], existing, plan["excluded"])
        assert [slot.to_json() for slot in missing] == plan["missing"]
    assert {"edge", "edge_rotated"} <= set(data["logs"])
    assert any(case["args"]["log"]["name"] == "edge" for case in data["valid"])
    assert any(case["args"]["log"]["name"] == "edge" for case in data["invalid"])
